import { parseSheet } from './sheet.js'
import { buildEvaluator, depsOf, formatValue, parseFormula } from './formula.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
const parsed = parseSheet(input)
if (parsed.error) {
  process.stderr.write(parsed.error + '\n')
  process.exit(2)
}

const cells = parsed.cells // sorted array of {addr, col, row, content}
let out = ''
if (mode === 'values') {
  const ev = buildEvaluator(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(ev.valueOf(c.addr))}\n`
} else {
  for (const c of cells) {
    let names = []
    if (c.content.startsWith('=')) {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) names = depsOf(p)
    }
    out += `${c.addr}:${names.map((n) => ' ' + n).join('')}\n`
  }
}
process.stdout.write(out)
"}

