{"file_path":"src/sheet.js","content":"export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1 ? letters.charCodeAt(0) - 64 : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, addr: letters + row, letters }
}

export function colName(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const k = col - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

export function addrOf(col, row) {
  return colName(col) + row
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Map()
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].replace(/^[ \t]+/, '')
    if (t === '' || t[0] === '#') continue
    let j = 0
    while (j < t.length && t[j] !== ' ' && t[j] !== '\t') j++
    const raw = t.slice(0, j)
    let k = j
    while (k < t.length && (t[k] === ' ' || t[k] === '\t')) k++
    const content = t.slice(k)
    const a = parseAddr(raw)
    if (!a) return { error: `error: line ${i + 1}: invalid cell address ${raw}` }
    if (seen.has(a.addr)) return { error: `error: line ${i + 1}: cell ${a.addr} is declared twice` }
    seen.set(a.addr, { addr: a.addr, col: a.col, row: a.row, content })
  }
  const cells = [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells }
}
"}

