{"file_path":"src/formula.js","content":"import { parseAddr, addrOf } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ k: 'num', v })
const err = (v) => ({ k: 'err', v })

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

class Fail extends Error {}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { ok: false }
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Fail() }
  const expect = (v) => { if (!isOp(v)) fail(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) fail()
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      expect(')')
      return { t: 'group', e }
    }
    if (tk.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            expect(')')
            break
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { t: 'range', a: tk.v, b: t2.v }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', a: tk.v }
    }
    return fail()
  }

  let tree
  try {
    tree = cmp()
    if (p !== toks.length) return { ok: false }
  } catch (e) {
    if (e instanceof Fail) return { ok: false }
    throw e
  }
  let misplaced = false
  const walk = (n, argPos) => {
    switch (n.t) {
      case 'range': if (!argPos) misplaced = true; break
      case 'bin': walk(n.l, false); walk(n.r, false); break
      case 'un': case 'group': walk(n.e, false); break
      case 'call': for (const a of n.args) walk(a, true); break
    }
  }
  walk(tree, false)
  return { ok: true, tree, misplaced }
}

function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r })
  return out
}

export function depsOf(parsed) {
  const set = new Map()
  const add = (col, row) => set.set(col * 10000 + row, { col, row })
  const walk = (n) => {
    switch (n.t) {
      case 'ref': { const a = parseAddr(n.a); if (a) add(a.col, a.row); break }
      case 'range': { const cs = rangeCells(n.a, n.b); if (cs) for (const c of cs) add(c.col, c.row); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'group': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(parsed.tree)
  return [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((c) => addrOf(c.col, c.row))
}

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    case 'err': return v.v
    default: return v.v
  }
}

function toNumber(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { num: 0, str: 1, bool: 2 }

function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 'str') {
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

export function buildEvaluator(cells) {
  const decl = new Map(cells.map((c) => [c.addr, c]))
  const memo = new Map()
  const busy = new Set()

  function literal(content) {
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.includes(content)) return err(content)
    return { k: 'str', v: content }
  }

  function valueOf(addr) {
    if (memo.has(addr)) return memo.get(addr)
    const c = decl.get(addr)
    if (!c) return num(0)
    if (busy.has(addr)) return err('#CYCLE!')
    busy.add(addr)
    let v
    if (c.content.startsWith('=')) {
      const p = parseFormula(c.content.slice(1))
      if (!p.ok || p.misplaced) v = err('#ERR!')
      else v = ev(p.tree)
    } else v = literal(c.content)
    busy.delete(addr)
    memo.set(addr, v)
    return v
  }

  function argValues(a) {
    if (a.t === 'range') {
      const cs = rangeCells(a.a, a.b)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => valueOf(addrOf(c.col, c.row)))
    }
    return [ev(a)]
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'group': return ev(n.e)
      case 'ref': {
        const a = parseAddr(n.a)
        return a ? valueOf(a.addr) : err('#REF!')
      }
      case 'un': {
        const v = ev(n.e)
        if (v.k === 'err') return v
        const x = toNumber(v)
        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return binary(n)
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function binary(n) {
    const l = ev(n.l)
    const r = ev(n.r)
    if (l.k === 'err') return l
    if (r.k === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const d = compare(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { k: 'bool', v: res }
    }
    const x = toNumber(l)
    if (x.k === 'err') return x
    const y = toNumber(r)
    if (y.k === 'err') return y
    switch (n.op) {
      case '+': return finite(x.v + y.v)
      case '-': return finite(x.v - y.v)
      case '*': return finite(x.v * y.v)
      case '/': return y.v === 0 ? err('#DIV/0!') : finite(x.v / y.v)
      case '^': return finite(Math.pow(x.v, y.v))
    }
    return err('#ERR!')
  }

  function call(n) {
    const name = n.name
    const k = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const c = argValues(n.args[0])
      if (c.length !== 1) return err('#ERR!')
      const cv = c[0]
      if (cv.k === 'err') return cv
      let t
      if (cv.k === 'bool') t = cv.v
      else if (cv.k === 'num') t = cv.v !== 0
      else return err('#VALUE!')
      const b = argValues(n.args[t ? 1 : 2])
      return b.length === 1 ? b[0] : err('#ERR!')
    }
    if (name === 'ABS' ? k !== 1 : k < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) vals.push(...argValues(a))
    const e = vals.find((v) => v.k === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNumber(v)
      if (x.k === 'err') return x
      nums.push(x.v)
    }
    if (name === 'ABS') return nums.length === 1 ? finite(Math.abs(nums[0])) : err('#ERR!')
    if (name === 'SUM') return finite(nums.reduce((s, x) => s + x, 0))
    if (name === 'AVG') {
      const s = nums.reduce((a, x) => a + x, 0)
      return finite(s / nums.length)
    }
    if (name === 'MIN') return num(nums.reduce((a, x) => (x < a ? x : a), Infinity))
    return num(nums.reduce((a, x) => (x > a ? x : a), -Infinity))
  }

  return { valueOf }
}
"}

