    if (memo.has(addr)) return memo.get(addr)
    const c = decl.get(addr)
    if (!c) return num(0)
    if (busy.has(addr)) return err('#CYCLE!')
    busy.add(addr)
    let v
    if (c.content.startsWith('=')) {
