    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'group': return ev(n.e)
      case 'ref': {
        const a = parseAddr(n.a)
        return a ? valueOf(a.addr) : err('#REF!')
      }
      case 'un': {
        const v = ev(n.e)
        if (v.k === 'err') return v
        const x = toNumber(v)
        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return binary(n)
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function binary(n) {
    const l = ev(n.l)
    const r = ev(n.r)
    if (l.k === 'err') return l
    if (r.k === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const d = compare(l, r)
      const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
      return { k: 'bool', v: res }
    }
    const x = toNumber(l)
    if (x.k === 'err') return x
    const y = toNumber(r)
    if (y.k === 'err') return y
